    kept_rows = []
    original_index = 0

    for row in rows:
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and '|' in row:
            try:
                weight = int(row.split('|')[1])
            except ValueError:
                weight = 0  # Handle potential errors in the string
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int) and not isinstance(item, bool):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + original_index) % 7 != 0 or original_index == len(rows) - 1:
            kept_rows.append((row, weight, original_index))
            state += weight
            state = (5 * state + weight) % 7 if state != 0 else 0
        else:
            state = 0

    if not kept_rows:
        return []

    kept_rows.sort(key=lambda x: x[0])
    result = {}
    for row, amount, _ in kept_rows:
        if row[0] not in result:
            result[row[0]] = 0
        if amount != 0:
            result[row[0]] += amount

    filtered_result = [(key, value) for key, value in result.items() if value != 0]
    filtered_result.sort(key=lambda x: x[0])
    return filtered_result

